def _ollama_generate(prompt, num_predict, timeout=60):
    resp = requests.post(OLLAMA_URL, json={
        "model": OLLAMA_MODEL,
        "prompt": prompt,
        "stream": False,
        "options": {"temperature": 0, "num_predict": num_predict},
    }, timeout=timeout)
    resp.raise_for_status()
    return resp.json()["response"].strip()
